using System.Security.Claims;using System.Security.Cryptography;using System.Text.Json;using EduForge.Domain;using EduForge.Infrastructure;using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;
public record CodeTest(string Input,string Expected);
public record AssignmentInput(string Title,string Description,string Kind,int MaxScore,List<CodeTest> Tests,string Rubric);
public record SubmissionInput(string Name,string Content,string Attachment);
public record RunInput(string Code,string Input);
public record GradeInput(int Score,string Feedback);
public static class AssignmentEndpoints {
 static Guid Owner(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public static void MapAssignments(this WebApplication app){var own=app.MapGroup("/api/assignments").RequireAuthorization();own.MapGet("/",async(ClaimsPrincipal u,MaterialDbContext db,CancellationToken ct)=>Results.Ok(await db.Assignments.Where(x=>x.TeacherId==Owner(u)).ToListAsync(ct)));
 own.MapPost("/",async(AssignmentInput input,ClaimsPrincipal u,MaterialDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(input.Title)||input.Title.Length>200||input.Description is null||input.Description.Length>10000||input.Rubric is null||input.Rubric.Length>4000||input.Kind is not("Python" or "HTML" or "Design" or "Model")||input.MaxScore is <1 or >1000||input.Tests is null||input.Tests.Count>10||input.Tests.Any(x=>x.Input is null||x.Expected is null||x.Input.Length>4000||x.Expected.Length>4000))return Results.BadRequest();var a=new Assignment{TeacherId=Owner(u),Title=input.Title,Description=input.Description,Kind=input.Kind,MaxScore=input.MaxScore,Tests=JsonSerializer.Serialize(input.Tests),Rubric=input.Rubric,Token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32))};db.Assignments.Add(a);await db.SaveChangesAsync(ct);return Results.Ok(a);});
 own.MapGet("/{id:guid}/submissions",async(Guid id,ClaimsPrincipal u,MaterialDbContext db,CancellationToken ct)=>{if(!await db.Assignments.AnyAsync(x=>x.Id==id&&x.TeacherId==Owner(u),ct))return Results.NotFound();return Results.Ok(await db.Submissions.Where(x=>x.AssignmentId==id).OrderByDescending(x=>x.At).ToListAsync(ct));});
 own.MapPost("/{id:guid}/submissions/{submissionId:guid}/grade",async(Guid id,Guid submissionId,GradeInput input,ClaimsPrincipal u,MaterialDbContext db,CancellationToken ct)=>{var a=await db.Assignments.SingleOrDefaultAsync(x=>x.Id==id&&x.TeacherId==Owner(u),ct);if(a is null)return Results.NotFound();if(input.Score<0||input.Score>a.MaxScore||input.Feedback is null||input.Feedback.Length>4000)return Results.BadRequest();var submission=await db.Submissions.SingleOrDefaultAsync(x=>x.Id==submissionId&&x.AssignmentId==id,ct);if(submission is null)return Results.NotFound();submission.Score=input.Score;submission.Feedback=input.Feedback;await db.SaveChangesAsync(ct);return Results.NoContent();});
 var student=app.MapGroup("/api/tasks/{token}").RequireRateLimiting("join");student.MapGet("/",async(string token,MaterialDbContext db,CancellationToken ct)=>{var a=await db.Assignments.SingleOrDefaultAsync(x=>x.Token==token,ct);return a is null?Results.NotFound():Results.Ok(new{a.Title,a.Description,a.Kind,a.MaxScore,a.Rubric});});
 student.MapPost("/run",async(string token,RunInput input,MaterialDbContext db,PythonRunner runner,CancellationToken ct)=>{if(!await db.Assignments.AnyAsync(x=>x.Token==token&&x.Kind=="Python",ct))return Results.NotFound();if(input.Code is null||input.Code.Length>20000||input.Input is null||input.Input.Length>4000)return Results.BadRequest();try{return Results.Ok(new{output=await runner.Run(input.Code,input.Input,ct)});}catch(PythonUnavailableException e){return Results.Problem(e.Message,statusCode:503);}catch(InvalidOperationException e){return Results.BadRequest(new{message=e.Message});}catch(System.ComponentModel.Win32Exception){return Results.Problem("Среда запуска кода не установлена.",statusCode:503);}}).RequireRateLimiting("code");
 student.MapPost("/submit",async(string token,SubmissionInput input,MaterialDbContext db,PythonRunner runner,CancellationToken ct)=>{var a=await db.Assignments.SingleOrDefaultAsync(x=>x.Token==token,ct);if(a is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(input.Name)||input.Name.Length>200||input.Content is null||input.Content.Length>20000||input.Attachment is null||input.Attachment.Length>2000||!input.Attachment.StartsWith($"/api/tasks/{token}/files/")&&input.Attachment!=""&&(!Uri.TryCreate(input.Attachment,UriKind.Absolute,out var url)||url.Scheme!="https"))return Results.BadRequest();if(input.Attachment.StartsWith("/api/")){if(!Guid.TryParse(input.Attachment.Split('/').Last(),out var assetId)||input.Attachment!=$"/api/tasks/{token}/files/{assetId}"||!await db.AssignmentAssets.AnyAsync(x=>x.Id==assetId&&x.AssignmentId==a.Id,ct))return Results.BadRequest();}var s=new AssignmentSubmission{AssignmentId=a.Id,Name=input.Name.Trim(),Content=input.Content,Attachment=input.Attachment};if(a.Kind=="Python"){var tests=JsonSerializer.Deserialize<List<CodeTest>>(a.Tests)!;if(tests.Count>0){var passed=0;try{foreach(var test in tests)if((await runner.Run(input.Content,test.Input,ct)).Trim()==test.Expected.Trim())passed++;s.Score=(int)Math.Round((double)passed/tests.Count*a.MaxScore);s.Feedback=$"Пройдено тестов: {passed}/{tests.Count}";}catch(PythonUnavailableException e){return Results.Problem(e.Message,statusCode:503);}catch(InvalidOperationException e){s.Score=0;s.Feedback=e.Message;}catch(System.ComponentModel.Win32Exception){return Results.Problem("Среда Python недоступна. Работа не отправлена.",statusCode:503);}}}db.Submissions.Add(s);await db.SaveChangesAsync(ct);return Results.Ok(new{s.Score,s.Feedback});}).RequireRateLimiting("code");
 }
}
